import sys

def solve():
    s = sys.stdin.read().rstrip('\r\n')
    if not s:
        print(0)
        return
    last_idx = {}
    max_len = 0
    left = 0
    for right, char in enumerate(s):
        if char in last_idx and last_idx[char] >= left:
            left = last_idx[char] + 1
        last_idx[char] = right
        max_len = max(max_len, right - left + 1)
    print(max_len)

if __name__ == '__main__':
    solve()

