#include <stdio.h>
#include <string.h>

int main() {
    char s[50005];
    if (!fgets(s, sizeof(s), stdin)) {
        printf("0\n");
        return 0;
    }
    int len = strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) {
        s[--len] = '\0';
    }
    int last[256];
    for (int i = 0; i < 256; i++) last[i] = -1;
    int maxLen = 0, left = 0;
    for (int right = 0; right < len; right++) {
        unsigned char c = (unsigned char)s[right];
        if (last[c] >= left) {
            left = last[c] + 1;
        }
        last[c] = right;
        int cur = right - left + 1;
        if (cur > maxLen) maxLen = cur;
    }
    printf("%d\n", maxLen);
    return 0;
}
